create table if not exists public.stock_movements(movement_id bigint generated always as identity primary key,movement_date timestamptz not null default now(),transaction_id bigint references public."transaction"(transaction_id) on delete set null,transaction_line_id bigint references public.transaction_line(transaction_line_id) on delete set null,product_id bigint not null references public.products(product_id),location_id bigint not null references public.locations(location_id),quantity numeric(24,6) not null,movement_type text not null,unit_cost numeric(24,6) not null default 0 check(unit_cost>=0));
create table if not exists public.stock_transfer(transfer_id bigint generated always as identity primary key,transfer_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,source_location_id bigint not null references public.locations(location_id),target_location_id bigint not null references public.locations(location_id),status_id bigint not null references public.status(status_id),check(source_location_id<>target_location_id));
create table if not exists public.stock_adjustment(adjustment_id bigint generated always as identity primary key,adjustment_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,location_id bigint not null references public.locations(location_id),account_id bigint not null references public.chart_accounts(account_id),reason text not null,total_cost numeric(24,6) not null default 0);
create table if not exists public.stock_reservation(reservation_id bigint generated always as identity primary key,product_id bigint not null references public.products(product_id) on delete cascade,location_id bigint not null references public.locations(location_id) on delete cascade,transaction_id bigint references public."transaction"(transaction_id) on delete cascade,quantity_reserved numeric(24,6) not null check(quantity_reserved>0),expiration_date timestamptz,unique(product_id,location_id,transaction_id));
do $$declare t text;begin foreach t in array array['stock_movements','stock_transfer','stock_adjustment','stock_reservation']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "inventory_select" on public.%I',t);execute format('drop policy if exists "inventory_insert" on public.%I',t);execute format('drop policy if exists "inventory_update" on public.%I',t);execute format('drop policy if exists "inventory_delete" on public.%I',t);execute format('create policy "inventory_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "inventory_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "inventory_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "inventory_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
